import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const home = homedir();
const version = '6.4.0';
const cache = join(home, '.npm', '_npx');
const packageRoot = readdirSync(cache)
  .map(directory => join(cache, directory, 'node_modules', 'rea-agents'))
  .find(directory => {
    const manifest = join(directory, 'package.json');
    return existsSync(manifest) && JSON.parse(readFileSync(manifest, 'utf8')).version === version;
  });
assert.ok(packageRoot, 'The installed REA package must be present in the npm cache');

const requireREA = createRequire(join(packageRoot, 'package.json'));
const { Client } = requireREA('@modelcontextprotocol/sdk/client/index.js');
const { StdioClientTransport } = requireREA('@modelcontextprotocol/sdk/client/stdio.js');
const skillDirectory = join(home, '.agents', 'skills', 'reverse-engineer-anything');
const skill = readFileSync(join(skillDirectory, 'SKILL.md'), 'utf8');
assert.match(skill, /^---\r?\nname: reverse-engineer-anything\r?\n/);
assert.equal(
  readFileSync(join(home, '.claude', 'skills', 'reverse-engineer-anything', 'SKILL.md'), 'utf8'),
  skill,
  'Claude Code and the shared skill must match',
);
for (const reference of skill.matchAll(/\]\((references\/[^)#]+)\)/g)) {
  assert.ok(existsSync(join(skillDirectory, reference[1])), `Missing skill reference: ${reference[1]}`);
}

const registrations = [
  ['claude_code', join(home, '.claude.json')],
  ['copilot_cli', join(home, '.copilot', 'mcp-config.json')],
  ['vscode', join(home, 'Library', 'Application Support', 'Code', 'User', 'mcp.json')],
];
const checks = [];
let analysisToolSchema;

for (const [name, configPath] of registrations) {
  const config = JSON.parse(readFileSync(configPath, 'utf8'));
  const container = config.mcpServers ? 'mcpServers' : 'servers';
  const registration = config[container]?.rea;
  assert.ok(registration, `${name}: REA must be registered`);
  assert.equal(registration.command, 'npx');
  assert.deepEqual(registration.args, ['-y', `rea-agents@${version}`, 'mcp']);

  const backupPath = `${configPath}.rea.backup`;
  if (existsSync(backupPath)) {
    const original = JSON.parse(readFileSync(backupPath, 'utf8'));
    const updated = structuredClone(config);
    for (const document of [original, updated]) {
      if (document[container]) {
        delete document[container].rea;
        if (Object.keys(document[container]).length === 0) delete document[container];
      }
    }
    assert.deepEqual(updated, original, `${name}: unrelated configuration must be preserved`);
  }

  const transport = new StdioClientTransport({
    command: registration.command,
    args: registration.args,
    env: { ...process.env, ...registration.env },
    stderr: 'inherit',
  });
  const client = new Client({ name: 'rea-install-smoke-test', version: '1.0.0' });
  try {
    await client.connect(transport);
    const { tools } = await client.listTools();
    assert.ok(tools.some(tool => tool.name === 'binary_session'));
    const analyzer = tools.find(tool => tool.name === 'analyze_javascript_application');
    assert.ok(analyzer, `${name}: JavaScript analysis must be advertised`);
    analysisToolSchema = analyzer.inputSchema;
    const session = await client.callTool({ name: 'binary_session', arguments: {} });
    assert.ok(!session.isError, `${name}: binary_session must succeed`);
    assert.ok(session.content?.length, `${name}: the tool must return a result`);
    checks.push({
      client: name,
      passed: true,
      backupChecked: existsSync(backupPath),
      server: client.getServerVersion(),
      advertisedTools: tools.length,
      toolCall: 'binary_session',
    });
  } finally {
    await client.close();
  }
}

const report = {
  testedAt: new Date().toISOString(),
  packageVersion: version,
  skillSha256: createHash('sha256').update(skill).digest('hex'),
  checks,
  analysisToolSchema,
  limitation: 'Tests the configured launchers directly; an already-open agent chat must reconnect to discover REA.',
};
writeFileSync(fileURLToPath(new URL('./verification.json', import.meta.url)), `${JSON.stringify(report, null, 2)}\n`);
console.log(JSON.stringify(report, null, 2));

