async function verifyMcp(registration) {
  const child = spawn(registration.command, registration.args, {
    env: { ...process.env, ...registration.env },
    detached: true,
    stdio: ['pipe', 'pipe', 'inherit'],
  });
  const lines = createInterface({ input: child.stdout });
  const messages = lines[Symbol.asyncIterator]();
  const terminate = () => {
    if (!child.pid) return;
    try {
      process.kill(-child.pid, 'SIGTERM');
    } catch (error) {
      if (error.code !== 'ESRCH') throw error;
    }
  };
  const deadline = setTimeout(terminate, 60_000);
  let requestId = 0;

  async function request(method, params) {
    requestId += 1;
    child.stdin.write(`${JSON.stringify({ jsonrpc: '2.0', id: requestId, method, params })}\n`);
    for await (const line of messages) {
      const message = JSON.parse(line);
      if (message.id !== requestId) continue;
      assert.ok(!message.error, JSON.stringify(message.error));
      return message.result;
    }
    throw new Error(`REA exited before replying to ${method}`);
  }

  try {
    await once(child, 'spawn');
    const initialized = await request('initialize', {
      protocolVersion: '2025-06-18',
      capabilities: {},
      clientInfo: { name: 'rea-install-smoke-test', version: '1.0.0' },
    });
    child.stdin.write(`${JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' })}\n`);
    const { tools } = await request('tools/list', {});
    assert.ok(tools.some(tool => tool.name === 'binary_session'));
    const analyzer = tools.find(tool => tool.name === 'analyze_javascript_application');
    assert.ok(analyzer, 'JavaScript analysis must be advertised');
    const session = await request('tools/call', { name: 'binary_session', arguments: {} });
    assert.ok(!session.isError, 'binary_session must succeed');
