function renderReport() {
  const signature = JSON.stringify([current.report,current.report_draft,current.status]);
  if (signature === reportCache) return;
  reportCache = signature;
  $('report').replaceChildren();
  if (!current.report) {
    if (current.status === 'reporting') {
      $('report').append(node('p','LIVE SYNTHESIS DRAFT · findings are validated before publication','stream-badge'),
        node('p',current.report_draft?.summary || 'Bringing the different arguments together…','report-summary'));
      if(current.report_draft?.conclusion) $('report').append(node('h3','Bottom line'),node('p',current.report_draft.conclusion,'conclusion'));
    } else $('report').append(node('p', 'A final synthesis appears after the conversation. It separates agreements, contested positions and open questions.', 'muted empty'));
    return;
  }
  const report = current.report;
  $('report').append(node('h3','Bottom line'),node('p',report.conclusion || report.summary,'conclusion'));
  if(report.conclusion) $('report').append(node('h3','How the conversation developed'));
  $('report').append(node('p', report.summary, 'report-summary'));
  const columns=node('div',undefined,'synthesis-columns');
  for(const [key,title] of [['agreements','Where they agreed'],['disagreements','Where they disagreed'],['open_questions','What remains unanswered']]) {
    if(!report[key]?.length) continue;
    const section=node('section');section.append(node('h3',title));const list=node('ul');
    for(const point of report[key])list.append(node('li',point));section.append(list);columns.append(section);
  }
  $('report').append(columns,node('h3','Evidence behind the synthesis'));
  for (const finding of report.findings) {
    const item = node('article', undefined, 'finding');
    item.append(node('p', finding.claim));
    for (const id of finding.action_ids) item.append(evidence(id));
    $('report').append(item);
  }
  $('report').append(node('div', report.limitations, 'limitations'));
}
function renderRun(run) {
  current = run;
  $('status').textContent = run.status;
  $('run-title').textContent = run.config.scenario;
  const descriptions = {
    preparing: 'Creating fictional personas from your context. No rounds have started.',
    ready: 'Review the cast below. Starting will send persona decisions and the discussion to the configured OpenAI endpoint.',
    running: 'Independent conversations run in parallel. Each reply waits for its partner’s finished argument; live bubbles show actual model text.',
    reporting: 'All rounds finished. Summarizing the evidence and checking citation IDs.',
    completed: 'Conversation complete. The Final synthesis tab has the bottom line, disagreements and evidence.',
    cancelled: 'Cancelled. Finished turns are saved; unfinished drafts are not evidence.',
    interrupted: 'Server restarted. Finished turns are saved; no paid calls were replayed.',
    failed: 'Stopped safely. Finished turns remain available; failed drafts are not evidence.'
  };
  $('run-description').textContent = descriptions[run.status] || run.status;
  $('agent-metric').textContent = run.agents.length || run.config.agent_count;
  $('round-metric').textContent = `${run.round} / ${run.config.rounds}`;
  $('token-metric').textContent = (run.usage.input_tokens + run.usage.output_tokens).toLocaleString();
  $('run-error').textContent = run.error || '';
  $('progress').max = run.config.rounds;
  $('progress').value = run.round;
  $('summary-preview').hidden = !run.report;
  $('summary-preview-text').textContent = run.report ? (run.report.conclusion || run.report.summary) : '';
  renderRoster(); renderFeed(); renderDrafts(); renderReport(); renderRoom(); updateControls();
}
async function refreshHistory() {
  history = await api('/api/runs');
  $('history').replaceChildren();
  if (!history.length) $('history').append(node('p', 'No experiments yet.', 'muted'));
  for (const run of history) {
    const button = node('button', undefined, 'history-item');
    button.type = 'button';
    button.setAttribute('aria-pressed', String(run.id === selectedId));
    button.append(node('strong', run.config.scenario), node('small', `${run.status} · ${run.config.agent_count} agents · ${run.round}/${run.config.rounds} rounds`));
    button.addEventListener('click', () => selectRun(run.id));
    $('history').append(button);
  }
  updateControls();
}
async function selectRun(id) {
  eventStream?.close();clearTimeout(replayTimer);playback=null;
  const ticket = ++generation;
  selectedId = id;
  rosterCache = reportCache = feedCache = '';
  drafts.clear();ConversationRoom.reset();
  error('');
  try {
    const run=await api(`/api/runs/${id}`);
    if(ticket!==generation)return;
    drafts=new Map((run.drafts||[]).map(d=>[d.turn_id,d]));
    renderRun(run);
    showView(run.report || run.status==='reporting'?'synthesis':'room');
    await refreshHistory();
    if(ticket!==generation || !activeStates.has(run.status))return;
    const source=new EventSource(`/api/runs/${id}/events?after=${run.event_cursor||0}`);
    eventStream=source;
    let cursor=run.event_cursor||0;
    source.addEventListener('update',event=>{
      if(ticket!==generation)return;
      const update=JSON.parse(event.data);
      if(update.id<=cursor)return;
      cursor=update.id;
      const data=update.data;
      if(update.kind==='turn_start' || update.kind==='turn_delta')drafts.set(data.turn_id,data);
      if(update.kind==='turn_abort')drafts.delete(data.turn_id);
      if(update.kind==='turn_complete'){
        drafts.delete(data.action.turn_id);
        if(!current.actions.some(a=>a.id===data.action.id))current.actions.push(data.action);
      }
      if(update.kind==='state'){
        if(data.status)current.status=data.status;
        if(data.round!==undefined)current.round=data.round;
        if(data.agents)current.agents=data.agents;
      }
      if(data.usage)current.usage=data.usage;
      if(update.kind==='report_start'){
        current.status='reporting';current.report_draft={};showView('synthesis');
      }
      if(update.kind==='report_delta') current.report_draft={...current.report_draft,...data};
      if(update.kind==='report_complete'){
        current.report=data.report;current.report_draft={};showView('synthesis');
      }
      if(update.kind==='terminal'){
