async function selectRun(id) {
  eventStream?.close();clearTimeout(replayTimer);playback=null;
  const ticket = ++generation;
  selectedId = id;
  rosterCache = reportCache = feedCache = '';
  drafts.clear();ConversationRoom.reset();
  error('');
  try {
    const run=await api(`/api/runs/${id}`);
    if(ticket!==generation)return;
    drafts=new Map((run.drafts||[]).map(d=>[d.turn_id,d]));
    renderRun(run);
    showView(run.report || run.status==='reporting'?'synthesis':'room');
    await refreshHistory();
    if(ticket!==generation || !activeStates.has(run.status))return;
    const source=new EventSource(`/api/runs/${id}/events?after=${run.event_cursor||0}`);
    eventStream=source;
    let cursor=run.event_cursor||0;
    source.addEventListener('update',event=>{
      if(ticket!==generation)return;
      const update=JSON.parse(event.data);
      if(update.id<=cursor)return;
      cursor=update.id;
      const data=update.data;
      if(update.kind==='turn_start' || update.kind==='turn_delta')drafts.set(data.turn_id,data);
      if(update.kind==='turn_abort')drafts.delete(data.turn_id);
      if(update.kind==='turn_complete'){
        drafts.delete(data.action.turn_id);
        if(!current.actions.some(a=>a.id===data.action.id))current.actions.push(data.action);
      }
      if(update.kind==='state'){
        if(data.status)current.status=data.status;
        if(data.round!==undefined)current.round=data.round;
        if(data.agents)current.agents=data.agents;
      }
      if(data.usage)current.usage=data.usage;
      if(update.kind==='report_start'){
        current.status='reporting';current.report_draft={};showView('synthesis');
      }
      if(update.kind==='report_delta') current.report_draft={...current.report_draft,...data};
      if(update.kind==='report_complete'){
        current.report=data.report;current.report_draft={};showView('synthesis');
      }
      if(update.kind==='terminal'){
        current.status=data.status;current.error=data.error;drafts.clear();current.report_draft={};
      }
      current.event_cursor=cursor;renderRun(current);
    });
    source.addEventListener('end',async()=>{
      source.close();
      try {
        const snapshot=await api(`/api/runs/${id}`);
        if(ticket!==generation)return;
        drafts.clear();renderRun(snapshot);await refreshHistory();
      } catch(exc){if(ticket===generation)error(exc.message);}
    });
    source.onerror=()=>{if(ticket===generation)$('room-state').textContent='Reconnecting live stream… saved turns remain intact';};
    source.onopen=()=>{if(ticket===generation)renderRoom();};
  } catch(exc) {
    if(ticket===generation)error(`${exc.message} Use Refresh to reconnect; your saved conversation has not been deleted.`);
  }
}
async function mutation(path, body) {
  busy = true; error(''); updateControls();
  try {
    const run = await api(path, body);
    if (run.id) await selectRun(run.id);
    return run;
  } catch (exc) {
    error(exc.message);
  } finally {
    busy = false; updateControls();
  }
}
