  $('report').replaceChildren();
  if (!current.report) {
    if (current.status === 'reporting') {
      $('report').append(node('p','LIVE SYNTHESIS DRAFT · findings are validated before publication','stream-badge'),
        node('p',current.report_draft?.summary || 'Bringing the different arguments together…','report-summary'));
      if(current.report_draft?.conclusion) $('report').append(node('h3','Bottom line'),node('p',current.report_draft.conclusion,'conclusion'));
