    const section=node('section');section.append(node('h3',title));const list=node('ul');
    for(const point of report[key])list.append(node('li',point));section.append(list);columns.append(section);
  }
  $('report').append(columns,node('h3','Evidence behind the synthesis'));
  for (const finding of report.findings) {
    const item = node('article', undefined, 'finding');
    item.append(node('p', finding.claim));
