'use strict';
window.ConversationRoom = (() => {
  const {THREE, OrbitControls} = MisofishAssets;
  const palette = ['#14705e','#c75d4d','#557fb5','#a7852f','#737fa1','#408a9f','#bc778b','#6a914d','#cd814c','#435d72'];
  const host = document.getElementById('room-lanes'), labels = document.getElementById('room-labels');
  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  let renderer, scene, camera, controls, cast = new Map(), signature = '', selected = null, paused = false, speaking = null;
  const material = color => new THREE.MeshStandardMaterial({color, roughness:0.8});
  function mesh(geometry, color, position, parent=scene) {
    const object = new THREE.Mesh(geometry, material(color));
    object.position.set(...position); object.castShadow = true; object.receiveShadow = true; parent.add(object); return object;
  }
  function resize() {
    if (!renderer || !host.clientWidth) return;
    const width = host.clientWidth, height = host.clientHeight, aspect = width / height;
    const span = aspect < 1.1 ? 10.8 : 8.6;
    camera.left = -span * aspect; camera.right = span * aspect; camera.top = span; camera.bottom = -span;
    camera.updateProjectionMatrix(); renderer.setSize(width,height,false);
  }
  function resetCamera() { if(camera){camera.position.set(16,19,20);controls.target.set(0,0,0);controls.update();} }
  function init() {
    try {
      renderer = new THREE.WebGLRenderer({antialias:true,alpha:false,preserveDrawingBuffer:true});
      renderer.setPixelRatio(Math.min(devicePixelRatio,2)); renderer.shadowMap.enabled = true;
      renderer.shadowMap.type = THREE.PCFSoftShadowMap; renderer.setClearColor('#edf3f4');
      host.prepend(renderer.domElement);
      scene = new THREE.Scene(); camera = new THREE.OrthographicCamera(-12,12,9,-9,0.1,100);
      controls = new OrbitControls(camera,renderer.domElement); controls.enableDamping = true;
      controls.minPolarAngle = 0.35; controls.maxPolarAngle = 1.2; controls.enablePan = false;
      controls.minZoom = 0.65; controls.maxZoom = 2.1; resetCamera();
      scene.add(new THREE.HemisphereLight('#ffffff','#a3b9b0',2.7));
      const light = new THREE.DirectionalLight('#ffffff',3); light.position.set(-8,15,10); light.castShadow=true;
      light.shadow.mapSize.set(2048,2048); Object.assign(light.shadow.camera,{left:-14,right:14,top:14,bottom:-14}); scene.add(light);
      mesh(new THREE.BoxGeometry(19,.3,16),'#dce7e5',[0,-.3,0]);
      mesh(new THREE.BoxGeometry(19,3,.25),'#e5eeef',[0,1.2,-8]);
      mesh(new THREE.BoxGeometry(.25,3,16),'#c4d7db',[-9.5,1.2,0]);
      const grid=new THREE.GridHelper(18,18,'#b7cdd0','#ccd9db');grid.position.y=-.13;scene.add(grid);
      mesh(new THREE.CylinderGeometry(2.2,2.2,.22,48),'#9fc1b4',[0,1,0]);
      mesh(new THREE.CylinderGeometry(.7,.9,.95,24),'#5b8277',[0,.42,0]);
      for (const position of [[6,0,-5],[-6,0,-5],[6,0,5]]) {
        mesh(new THREE.CylinderGeometry(.5,.4,.7,20),'#b6c4ca',[position[0],.2,position[2]]);
        mesh(new THREE.ConeGeometry(.85,1.9,8),'#688d69',[position[0],1.3,position[2]]);
      }
      for(const horizontal of [-5,0,5]) {
        mesh(new THREE.BoxGeometry(3.4,1.8,.08),'#90b8c9',[horizontal,1.55,-7.82]);
        mesh(new THREE.BoxGeometry(.07,1.9,.1),'#ffffff',[horizontal,1.55,-7.75]);
      }
      mesh(new THREE.BoxGeometry(3.8,.25,1.1),'#b5c4ce',[7,.6,1]);
      mesh(new THREE.BoxGeometry(3.8,1,.2),'#9cabb8',[7,1,1.5]);
      new ResizeObserver(resize).observe(host);
      renderer.domElement.addEventListener('click',event=>{
        const bounds=renderer.domElement.getBoundingClientRect();
        const pointer=new THREE.Vector2((event.clientX-bounds.left)/bounds.width*2-1,-(event.clientY-bounds.top)/bounds.height*2+1);
        const ray=new THREE.Raycaster();ray.setFromCamera(pointer,camera);
        for(const hit of ray.intersectObjects([...cast.values()].map(person=>person.group),true)) {
          let object=hit.object;while(object && !object.userData.agentId)object=object.parent;
          if(object){choose(object.userData.agentId);break;}
        }
      });
      animate();
    } catch(error) {
      const message=document.createElement('p');message.className='canvas-error';message.textContent='3D scene unavailable. Persona selection and discussion remain available.';host.append(message);
    }
  }
  function choose(id) { selected=id;window.dispatchEvent(new CustomEvent('persona-select',{detail:id})); }
  function person(actor,index,count) {
    const group=new THREE.Group();group.userData.agentId=actor.id;scene.add(group);
    const color=palette[index%palette.length],skin=['#deb08d','#ac7655','#efc6a3','#885b43'][index%4];
    mesh(new THREE.CapsuleGeometry(.32,.6,5,12),color,[0,1.12,0],group);
    mesh(new THREE.SphereGeometry(.31,16,12),skin,[0,1.92,0],group);
    mesh(new THREE.SphereGeometry(.32,16,8,0,Math.PI*2,0,1.1),'#394143',[0,2.02,0],group);
    const legs=[];
    for(const side of [-1,1]) {
      legs.push(mesh(new THREE.CapsuleGeometry(.13,.55,4,8),'#465665',[side*.19,.42,0],group));
      mesh(new THREE.CapsuleGeometry(.105,.55,4,8),skin,[side*.48,1.12,0],group);
      mesh(new THREE.BoxGeometry(.23,.13,.4),'#263438',[side*.19,.06,.07],group);
      mesh(new THREE.SphereGeometry(.025,8,6),'#263438',[side*.11,1.96,.29],group);
    }
    const ring=mesh(new THREE.TorusGeometry(.62,.035,6,32),color,[0,.015,0],group);ring.rotation.x=-Math.PI/2;
    const angle=index/count*Math.PI*2, radius=count>20?6.2:4.7;
    group.position.set(Math.cos(angle)*radius,0,Math.sin(angle)*radius);
    group.rotation.y=-angle-Math.PI/2;
    const label=document.createElement('button');label.className='room-label';label.type='button';label.textContent=actor.name;
    label.setAttribute('aria-label',`Inspect ${actor.name}`);label.style.setProperty('--persona-color',color);label.addEventListener('click',()=>choose(actor.id));labels.append(label);
    return {group,label,ring,legs,target:group.position.clone(),actor};
  }
  function render(run,unused=[],speech=null) {
    if(!renderer)return;
    const next=run.id+JSON.stringify(run.agents.map(actor=>actor.id));
    if(next!==signature){
      signature=next;
      for(const item of cast.values()){scene.remove(item.group);item.group.traverse(object=>{object.geometry?.dispose();object.material?.dispose();});item.label.remove();}
      cast=new Map();
      const visible=run.agents.slice(0,100);
      visible.forEach((actor,index)=>cast.set(actor.id,person(actor,index,visible.length)));
    }
    speaking=speech?.agent_id || null;
    for(const [id,item] of cast){
      item.label.setAttribute('aria-pressed',String(id===selected));item.ring.material.color.set(id===selected?'#f08368':palette[(id-1)%palette.length]);
      const index=[...cast.keys()].indexOf(id),angle=index/cast.size*Math.PI*2;
      const radius=id===speaking ? 3 : cast.size>20?6.2:4.7;
      item.target.set(Math.cos(angle)*radius,0,Math.sin(angle)*radius);
    }
    resize();
  }
  function animate(time=0) {
    requestAnimationFrame(animate);
    if(!host.clientWidth || !host.clientHeight)return;
    controls.update();
    for(const [id,item] of cast){
      const moving=item.group.position.distanceTo(item.target)>.02;
      if(!paused){
        if(reduced.matches)item.group.position.copy(item.target);else item.group.position.lerp(item.target,.035);
        item.legs.forEach((leg,index)=>leg.rotation.x=moving&&!reduced.matches?Math.sin(time*.008+index*Math.PI)*.22:0);
      }
      item.ring.scale.setScalar(id===speaking?1.25:1);
      const point=item.group.position.clone().add(new THREE.Vector3(0,2.65,0)).project(camera);
      item.label.style.left=`${(point.x+1)/2*host.clientWidth}px`;item.label.style.top=`${(-point.y+1)/2*host.clientHeight}px`;
      item.label.hidden=point.z>1 || point.x < -.98 || point.x > .98 || point.y < -.98 || point.y > .98;
    }
    renderer.render(scene,camera);
  }
  init();
  return {render,wake:resize,resetCamera,select:id=>{selected=id;},palette,
    pause:()=>{paused=!paused;return paused;},reset:()=>{signature='';selected=null;}};
})();

'use strict';
const $=id=>document.getElementById(id), activeStates=new Set(['preparing','running','reporting']);
const views=['room','graph','transcript','synthesis'];
let settings,current,history=[],stream,generation=0,busy=false,selectedPersona=null,graphRenderer,graphSignature='';
let paused=false,viewerIndex=-1,followLive=true,playbackTimer,speed=1,seenSpeech=new Set(),drafts=new Map();
const node=(tag,text,className)=>{const element=document.createElement(tag);if(text!==undefined)element.textContent=text;if(className)element.className=className;return element;};
const icon=(name)=>{const element=node('i');element.dataset.lucide=name;return element;};
const icons=()=>MisofishAssets.createIcons({icons:MisofishAssets.icons});
function error(message){$('error').textContent=message;$('error').hidden=!message;}
async function api(path,body){const response=await fetch(path,{...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),signal:AbortSignal.timeout(15000)});const result=await response.json();if(!response.ok)throw new Error(result.error||`Request failed (${response.status})`);return result;}
function showView(view){for(const name of views){$('view-'+name).hidden=name!==view;$('tab-'+name).setAttribute('aria-selected',String(name===view));$('tab-'+name).tabIndex=name===view?0:-1;}if(view==='room')ConversationRoom.wake();if(view==='graph')renderGraph();}
function speech(){return (current?.actions||[]).filter(action=>action.text&&action.kind!=='pass');}
function viewer(){
  const items=speech(),action=items[viewerIndex];
  $('backlog').textContent=`${Math.max(0,items.length-viewerIndex-1)} queued`;
  $('speech-meta').textContent=action?`${current.agents.find(actor=>actor.id===action.agent_id)?.name||'Persona '+action.agent_id} / A${action.id} / ${action.visibility||'legacy'} / ${action.engine_kind||action.kind}`:'No Speech Selected';
  $('selected-speech').textContent=action?.text||'No committed discussion yet.';
  $('playback-pause').setAttribute('aria-pressed',String(paused));
  $('playback-pause').setAttribute('aria-label',paused?'Resume playback':'Pause playback');
  $('playback-pause').title=paused?'Resume playback':'Pause playback';
  $('playback-pause').replaceChildren(icon(paused?'play':'pause'));
  $('catch-up').setAttribute('aria-pressed',String(followLive));
  if(current)ConversationRoom.render(current,[],action);
  icons();
}
function schedulePlayback(){clearTimeout(playbackTimer);if(paused||!current)return;const items=speech();if(viewerIndex<items.length-1){playbackTimer=setTimeout(()=>{viewerIndex++;viewer();schedulePlayback();},Math.max(900,5000/speed));}}
function evidence(id){const link=node('a','A'+id,'evidence');link.href='#action-'+id;link.addEventListener('click',event=>{event.preventDefault();$('agent-filter').value='all';showView('transcript');renderFeed();requestAnimationFrame(()=>$('action-'+id)?.scrollIntoView({block:'nearest'}));});return link;}
function inspectEntity(identity){
  const graph=current?.graph,item=graph?.nodes.find(record=>record.id===identity)||graph?.edges.find(record=>record.id===identity);
  if(!item)return;
  const host=$('inspector-content');host.replaceChildren(node('span',item.kind,'status'),node('h3',item.name||item.fact),node('p',item.summary||item.fact));
  host.append(node('p',item.synthetic?'Synthetic Scenario Evidence':'Source Quotation / Model-Extracted Relation','provenance'));
  for(const span of item.evidence||[]){host.append(node('blockquote',span.quote),node('p',`${span.source_id} / characters ${span.start}-${span.end}`,'provenance'));}
  const linked=current.agents.filter(actor=>actor.profile?.entity_id===identity);
  for(const actor of linked){const button=node('button',actor.name);button.addEventListener('click',()=>selectPersona(actor.id));host.append(button);}
}
function selectPersona(id){
  selectedPersona=id;ConversationRoom.select(id);
