function viewer(){
  const items=speech(),action=items[viewerIndex];
  $('backlog').textContent=`${Math.max(0,items.length-viewerIndex-1)} queued`;
  $('speech-meta').textContent=action?`${current.agents.find(actor=>actor.id===action.agent_id)?.name||'Persona '+action.agent_id} / A${action.id} / ${action.visibility||'legacy'} / ${action.engine_kind||action.kind}`:'No Speech Selected';
  $('selected-speech').textContent=action?.text||'No committed discussion yet.';
  $('playback-pause').setAttribute('aria-pressed',String(paused));
  $('playback-pause').setAttribute('aria-label',paused?'Resume playback':'Pause playback');
  $('playback-pause').title=paused?'Resume playback':'Pause playback';
  $('playback-pause').replaceChildren(icon(paused?'play':'pause'));
