function schedulePlayback(){clearTimeout(playbackTimer);if(paused||!current)return;const items=speech();if(viewerIndex<items.length-1){playbackTimer=setTimeout(()=>{viewerIndex++;viewer();schedulePlayback();},Math.max(900,5000/speed));}}
