import concurrent.futures
import json
import re
import urllib.parse
import urllib.request
import xml.etree.ElementTree as ET
from collections import Counter, defaultdict

BUCKETS = ("indian-supreme-court-judgments", "indian-high-court-judgments")
KINDS = {"metadata.index.json": "metadata", "english.index.json": "english", "data.index.json": "data", "regional.index.json": "regional"}
NS = {"s": "http://s3.amazonaws.com/doc/2006-03-01/"}

def get(url):
    last = None
    for _ in range(3):
        try:
            with urllib.request.urlopen(url, timeout=60) as response:
                return response.read()
        except Exception as exc:
            last = exc
    raise last

def list_bucket(bucket):
    token = None
    stats = {"objects": 0, "bytes": 0, "by_prefix": defaultdict(lambda: [0, 0]), "indexes": []}
    while True:
        params = {"list-type": "2", "max-keys": "1000"}
        if token:
            params["continuation-token"] = token
        url = f"https://{bucket}.s3.ap-south-1.amazonaws.com/?{urllib.parse.urlencode(params)}"
        root = ET.fromstring(get(url))
        for item in root.findall("s:Contents", NS):
            key = item.findtext("s:Key", namespaces=NS)
            size = int(item.findtext("s:Size", default="0", namespaces=NS))
            stats["objects"] += 1
            stats["bytes"] += size
            top = "/".join(key.split("/")[:2]) if "/" in key else "(root)"
            stats["by_prefix"][top][0] += 1
            stats["by_prefix"][top][1] += size
            if key.rsplit("/", 1)[-1] in KINDS:
                stats["indexes"].append(key)
        truncated = root.findtext("s:IsTruncated", default="false", namespaces=NS).lower() == "true"
        if not truncated:
            return stats
        token = root.findtext("s:NextContinuationToken", namespaces=NS)
        if not token:
            raise RuntimeError(f"Missing continuation token for {bucket}")

def read_index(arg):
    bucket, key = arg
    url = f"https://{bucket}.s3.ap-south-1.amazonaws.com/{urllib.parse.quote(key, safe='/')}"
    value = json.loads(get(url))
    code_match = re.search(r"court=([^/]+)", key)
    year_match = re.search(r"year=(\d{4})", key)
    kind = KINDS[key.rsplit("/", 1)[-1]]
    size = value.get("total_size", value.get("tar_size"))
    if size is None:
        size = sum(part.get("size", 0) for part in value.get("parts", []))
    return bucket, kind, code_match.group(1) if code_match else "supreme-court", int(year_match.group(1)) if year_match else None, value.get("file_count"), int(size or 0), key

stats = {}
for bucket in BUCKETS:
    print(f"Listing {bucket}...", flush=True)
    stats[bucket] = list_bucket(bucket)
    print(f"  {stats[bucket]['objects']:,} objects, {stats[bucket]['bytes']:,} bytes, {len(stats[bucket]['indexes']):,} indexes", flush=True)

args = [(bucket, key) for bucket in BUCKETS for key in stats[bucket]["indexes"]]
rows, failures = [], []
with concurrent.futures.ThreadPoolExecutor(max_workers=16) as pool:
    futures = {pool.submit(read_index, arg): arg for arg in args}
    for future in concurrent.futures.as_completed(futures):
        try:
            rows.append(future.result())
        except Exception as exc:
            failures.append((futures[future], str(exc)))

for bucket in BUCKETS:
    print(f"\n{bucket}")
    print("Storage by key prefix (object count, bytes):")
    for prefix, (count, size) in sorted(stats[bucket]["by_prefix"].items()):
        print(f"  {prefix:24} {count:8,} {size:15,}")
    kind_totals = defaultdict(lambda: [0, 0, 0])
    court_totals = defaultdict(lambda: defaultdict(int))
    for row_bucket, kind, court, year, count, size, key in rows:
        if row_bucket != bucket:
            continue
        if count is not None:
            kind_totals[kind][0] += count
        kind_totals[kind][1] += size
        kind_totals[kind][2] += 1
        if count is not None:
            court_totals[court][kind] += count
    print("Index totals (indexed files, index-reported archive bytes, index count):")
    for kind, values in sorted(kind_totals.items()):
        print(f"  {kind:10} {values[0]:12,} {values[1]:15,} {values[2]:8,}")
    if bucket.endswith("high-court-judgments"):
        print("High Court metadata/English/data counts by court code:")
        for court, values in sorted(court_totals.items()):
            print(f"  {court:8} metadata={values['metadata']:>10,} english={values['english']:>10,} data={values['data']:>10,} regional={values['regional']:>10,}")
print(f"\nIndex read failures: {len(failures)} of {len(args)}")
for arg, error in failures[:10]:
    print("FAILED", arg, error)
PY

