import urllib.parse, urllib.request, xml.etree.ElementTree as ET, re
ns={'s':'http://s3.amazonaws.com/doc/2006-03-01/'}
for bucket,prefix in [('indian-supreme-court-judgments','metadata/parquet/'),('indian-high-court-judgments','metadata/parquet/')]:
 token=None; courts=set(); years=set(); count=size=0
 while True:
  q={'list-type':'2','prefix':prefix,'max-keys':'1000'}
  if token: q['continuation-token']=token
  root=ET.fromstring(urllib.request.urlopen(f'https://{bucket}.s3.ap-south-1.amazonaws.com/?{urllib.parse.urlencode(q)}',timeout=60).read())
  for item in root.findall('s:Contents',ns):
   key=item.findtext('s:Key',namespaces=ns); count+=1; size+=int(item.findtext('s:Size',default='0',namespaces=ns))
   c=re.search(r'court=([^/]+)',key); y=re.search(r'year=(\d{4})',key)
   if c: courts.add(c.group(1))
   if y: years.add(y.group(1))
  if root.findtext('s:IsTruncated',default='false',namespaces=ns).lower()!='true': break
  token=root.findtext('s:NextContinuationToken',namespaces=ns)
 print(bucket,'objects',count,'bytes',size,'court_partitions',len(courts),'years',min(years) if years else '-',max(years) if years else '-',flush=True)
try:
 import duckdb
 print('DuckDB available for Parquet inspection')
except ImportError:
 print('DuckDB unavailable locally')
PY

