import pyarrow.parquet as pq
tbl = pq.read_table("data/open_india_law/raw/in_central_legislation.parquet", columns=["act_id", "title", "section_number", "section_title", "doc_type", "instrument_type"])
const_titles = {}
for aid, t, dt in zip(tbl["act_id"].to_pylist(), tbl["title"].to_pylist(), tbl["doc_type"].to_pylist()):
    if t and ("constitution" in t.lower() or "fundamental" in t.lower() or (dt and "constitution" in dt.lower())):
        const_titles[(aid, t, dt)] = const_titles.get((aid, t, dt), 0) + 1
print("Constitution matches in central legislation:", len(const_titles))
for k, v in sorted(const_titles.items(), key=lambda kv: -kv[1]):
    print(f"  {v:5d} | {k}")
rbi = pq.read_table("data/open_india_law/raw/in_rbi_regulations.parquet", columns=["act_id", "title", "section_title", "text"])
rbi_matches = {}
for aid, t, txt in zip(rbi["act_id"].to_pylist(), rbi["title"].to_pylist(), rbi["text"].to_pylist()):
    blob = ((t or "") + " " + (txt or "")).lower()
    if any(k in blob for k in ("cheque", "dishonour", "negotiable instrument", "clearing", "ecs", "nach", "payment and settlement", "drawee", "drawer")):
        rbi_matches[(aid, t)] = rbi_matches.get((aid, t), 0) + 1
print("RBI cheque/dishonour/payment matches:", len(rbi_matches), "total provisions:", sum(rbi_matches.values()))
for k, v in sorted(rbi_matches.items(), key=lambda kv: -kv[1])[:15]:
    print(f"  {v:5d} | {k[0]} | {k[1]}")
'

