import io, re, ssl, truststore, urllib.request, pyarrow.parquet as pq
ctx = truststore.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
ua = {"User-Agent": "Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7) OpenIndiaLawClient/1.0"}

class SparseBufferFile(io.RawIOBase):
    def __init__(self, size, segments): self.size, self.segments, self.pos = size, segments, 0
    def readable(self): return True
    def seekable(self): return True
    def seek(self, offset, whence=io.SEEK_SET):
        self.pos = offset if whence == io.SEEK_SET else (self.pos + offset if whence == io.SEEK_CUR else self.size + offset)
        return self.pos
    def tell(self): return self.pos
    def read(self, n=-1):
        for start, buf in self.segments:
            if start <= self.pos < start + len(buf):
                s = self.pos - start
                data = buf[s : None if n < 0 else s + n]
                self.pos += len(data)
                return data
        raise RuntimeError(f"Unbuffered read at {self.pos}")

def fetch_range(url, start, end):
    req = urllib.request.Request(url, headers={**ua, "Range": f"bytes={start}-{end - 1}"})
    with urllib.request.urlopen(req, context=ctx, timeout=90) as r:
        return start, r.read()

def col_span(rg_meta, col_indices):
    starts, ends = [], []
    for idx in col_indices:
        c = rg_meta.column(idx)
        s = c.dictionary_page_offset if c.has_dictionary_page and c.dictionary_page_offset else c.data_page_offset
        starts.append(s)
        ends.append(s + c.total_compressed_size)
    return min(starts), max(ends)

NI_RE = re.compile(r"section\s+138|s\.\s*138|138\s+of\s+the\s+negotiable|negotiable\s+instruments\s+act|dishonour\s+of\s+cheque|cheque\s+bounce", re.I)
CONTRACT_RE = re.compile(r"indian\s+contract\s+act|specific\s+relief\s+act|breach\s+of\s+contract|section\s+7[34]\b|section\s+5[56]\b|liquidated\s+damages|specific\s+performance", re.I)

for name, size in [("in_supreme-court_judgments.parquet", 3761559020), ("in_delhi_judgments.parquet", 1988058409), ("in_bombay_judgments.parquet", 4341270597)]:
    url = f"https://oss-data-in.vaquill.ai/v2026.08.1/{name}"
    _, footer = fetch_range(url, size - 2100000, size)
    pf_meta = pq.ParquetFile(SparseBufferFile(size, [(size - len(footer), footer)]))
    n_rg = pf_meta.num_row_groups
    sample_rgs = [0, n_rg // 2, n_rg - 1]
    for rg in sample_rgs:
        rg_meta = pf_meta.metadata.row_group(rg)
        s1, e1 = col_span(rg_meta, [0, 1, 2, 3, 4])
        s2, e2 = col_span(rg_meta, list(range(6, 31)))
        sbf = SparseBufferFile(size, [fetch_range(url, s1, e1), fetch_range(url, s2, e2), (size - len(footer), footer)])
        tbl = pq.ParquetFile(sbf).read_row_group(rg, columns=["case_id", "language_code", "year", "text"])
        cases = set()
        ni_cases, con_cases = set(), set()
        years = set()
        for cid, lang, yr, txt in zip(tbl["case_id"].to_pylist(), tbl["language_code"].to_pylist(), tbl["year"].to_pylist(), tbl["text"].to_pylist()):
            if lang != "en": continue
            cases.add(cid)
            if yr: years.add(yr)
            if txt:
                if NI_RE.search(txt): ni_cases.add(cid)
                if CONTRACT_RE.search(txt): con_cases.add(cid)
        print(f"{name} rg={rg}/{n_rg} en_cases={len(cases)} years={min(years) if years else None}-{max(years) if years else None} ni_cases={len(ni_cases)} contract_cases={len(con_cases)}")
'

