import io, re, ssl, truststore, urllib.request, pyarrow.parquet as pq
ctx = truststore.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
ua = {"User-Agent": "Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7) OpenIndiaLawClient/1.0"}

class SparseBufferFile(io.RawIOBase):
    def __init__(self, size, segments): self.size, self.segments, self.pos = size, segments, 0
    def readable(self): return True
    def seekable(self): return True
    def seek(self, offset, whence=io.SEEK_SET):
        self.pos = offset if whence == io.SEEK_SET else (self.pos + offset if whence == io.SEEK_CUR else self.size + offset)
        return self.pos
    def tell(self): return self.pos
    def read(self, n=-1):
        for start, buf in self.segments:
            if start <= self.pos < start + len(buf):
                s = self.pos - start
                data = buf[s : None if n < 0 else s + n]
                self.pos += len(data)
                return data
        raise RuntimeError(f"Unbuffered read at {self.pos}")

def fetch_range(url, start, end):
    req = urllib.request.Request(url, headers={**ua, "Range": f"bytes={start}-{end - 1}"})
    with urllib.request.urlopen(req, context=ctx, timeout=90) as r:
        return start, r.read()

def col_span(rg_meta, col_indices):
    starts, ends = [], []
    for idx in col_indices:
        c = rg_meta.column(idx)
        s = c.dictionary_page_offset if c.has_dictionary_page and c.dictionary_page_offset else c.data_page_offset
        starts.append(s)
        ends.append(s + c.total_compressed_size)
    return min(starts), max(ends)

